   ]
  },
  {
   "action": "Check the edge layer (DNS, CDN, load balancer) and client-side errors, and run a synthetic checkout end to end.",
   "rationale": "Backend services look healthy while traffic dipped late in the window, which fits customers failing before their requests reach the gateway.",
   "evidence_ids": [
    "ev-be0e298b6f6f"
   ]
  },
  {
   "action": "Find out why the trace and log queries returned nothing, and re-run them once fixed.",
   "rationale": "Services were handling traffic, so having no traces or logs at all suggests broken instrumentation or ingestion that may be hiding the failure.",
   "evidence_ids": [
    "src-traces",
    "src-logs"
   ]
  },
  {
   "action": "Review recent config, feature-flag and infrastructure changes outside the deployment record, and confirm the deployment query covered all relevant services.",
   "rationale": "No deployments were found, but an untracked change could still explain a sudden total outage.",
